<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';require_once __DIR__ . '/../includes/auth.php';
$user=current_user();if(!$user||!in_array($user['role'],['Administrator','Head'],true)){http_response_code(403);exit('Access denied.');}
if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf()){http_response_code(419);exit('This form has expired. Refresh the page and try again.');}
$op=(string)($_POST['operation']??'');$term=filter_var($_POST['term_id']??null,FILTER_VALIDATE_INT);$class=filter_var($_POST['class_id']??null,FILTER_VALIDATE_INT);$back='../?page=academics&tab=timetable'.($term?'&term_id='.(int)$term:'').($class?'&class_id='.(int)$class:'');$pdo=db();
try{
 if($op==='delete'){$slot=filter_var($_POST['slot_id']??null,FILTER_VALIDATE_INT);if(!$slot)throw new DomainException('Select a valid timetable period.');$pdo->beginTransaction();$q=$pdo->prepare('SELECT id,class_id,term_id FROM timetable_slots WHERE id=:id FOR UPDATE');$q->execute(['id'=>$slot]);$row=$q->fetch();if(!$row)throw new DomainException('Timetable period not found.');$del=$pdo->prepare('DELETE FROM timetable_slots WHERE id=:id');$del->execute(['id'=>$slot]);audit_log('timetable.period_removed','timetable_slots',$slot,['class_id'=>(int)$row['class_id'],'term_id'=>(int)$row['term_id']]);$pdo->commit();$_SESSION['notice']='Timetable period removed.';header('Location: '.$back);exit;}
 if($op!=='create'||!$term||!$class)throw new DomainException('Choose a valid term and class.');$allocation=filter_var($_POST['class_subject_id']??null,FILTER_VALIDATE_INT);$weekday=filter_var($_POST['weekday']??null,FILTER_VALIDATE_INT);$period=filter_var($_POST['period_number']??null,FILTER_VALIDATE_INT);$start=(string)($_POST['starts_at']??'');$end=(string)($_POST['ends_at']??'');$venue=trim((string)($_POST['venue']??''));if(!$allocation||$weekday===false||$weekday<1||$weekday>6||$period===false||$period<1||$period>12||!preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d$/',$start)||!preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d$/',$end)||$start>=$end||strlen($venue)>80)throw new DomainException('Enter a weekday, period number, valid time range and venue.');
 $pdo->beginTransaction();$termLock=$pdo->prepare('SELECT academic_year FROM school_terms WHERE id=:term FOR UPDATE');$termLock->execute(['term'=>$term]);$termYear=$termLock->fetchColumn();if(!$termYear)throw new DomainException('The selected school term no longer exists.');$q=$pdo->prepare('SELECT cs.id,cs.class_id,COALESCE(cs.teacher_id,c.class_teacher_id) AS teacher_id,c.form_level,c.academic_year,t.academic_year AS term_year FROM class_subjects cs JOIN class_groups c ON c.id=cs.class_id JOIN school_terms t ON t.id=:term WHERE cs.id=:allocation AND cs.class_id=:class FOR UPDATE');$q->execute(['term'=>$term,'allocation'=>$allocation,'class'=>$class]);$context=$q->fetch();if(!$context||(int)$context['academic_year']!==(int)$context['term_year']||(int)$context['term_year']!==(int)$termYear)throw new DomainException('The selected class, subject and term do not match.');
 $conflict=$pdo->prepare('SELECT ts.id FROM timetable_slots ts WHERE ts.term_id=:term AND ts.weekday=:weekday AND ts.class_id=:class AND ts.starts_at<:class_end AND ts.ends_at>:class_start LIMIT 1 FOR UPDATE');$conflict->execute(['term'=>$term,'weekday'=>$weekday,'class'=>$class,'class_end'=>$end.':00','class_start'=>$start.':00']);if($conflict->fetch())throw new DomainException('This class already has a period at an overlapping time.');
 if($context['teacher_id']){$conflict=$pdo->prepare('SELECT id FROM timetable_slots WHERE term_id=:term AND weekday=:weekday AND teacher_id=:teacher AND starts_at<:teacher_end AND ends_at>:teacher_start LIMIT 1 FOR UPDATE');$conflict->execute(['term'=>$term,'weekday'=>$weekday,'teacher'=>$context['teacher_id'],'teacher_end'=>$end.':00','teacher_start'=>$start.':00']);if($conflict->fetch())throw new DomainException('The assigned teacher already has a class at an overlapping time.');}
 if($venue!==''){$conflict=$pdo->prepare('SELECT id FROM timetable_slots WHERE term_id=:term AND weekday=:weekday AND LOWER(venue)=LOWER(:venue) AND starts_at<:room_end AND ends_at>:room_start LIMIT 1 FOR UPDATE');$conflict->execute(['term'=>$term,'weekday'=>$weekday,'venue'=>$venue,'room_end'=>$end.':00','room_start'=>$start.':00']);if($conflict->fetch())throw new DomainException('This venue is already booked at an overlapping time.');}
 $insert=$pdo->prepare('INSERT INTO timetable_slots (term_id,class_id,class_subject_id,teacher_id,weekday,period_number,starts_at,ends_at,venue,created_by) VALUES (:term,:class,:allocation,:teacher,:weekday,:period,:start,:end,:venue,:user)');$insert->execute(['term'=>$term,'class'=>$class,'allocation'=>$allocation,'teacher'=>$context['teacher_id'],'weekday'=>$weekday,'period'=>$period,'start'=>$start.':00','end'=>$end.':00','venue'=>$venue?:null,'user'=>$user['id']]);$id=(int)$pdo->lastInsertId();audit_log('timetable.period_created','timetable_slots',$id,['class_id'=>$class,'teacher_id'=>$context['teacher_id'],'weekday'=>$weekday,'period'=>$period]);$pdo->commit();$_SESSION['notice']='Timetable period added.';
}catch(DomainException $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['error']=$e->getMessage();}catch(PDOException $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Timetable save failed: '.$e->getMessage());$_SESSION['error']=$e->getCode()==='23000'?'That class or teacher already has a period with this number.':'Could not save this timetable period.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Timetable save failed: '.$e->getMessage());$_SESSION['error']='Could not save this timetable period.';}
header('Location: '.$back);exit;
